export class ReadOfferingResponseData extends OmitType(CreateOfferingDTO, ['dimensionIds', 'businessID'] as const) {
    /**
     * Unique identifier assigned by Enterprise.
     * <br><br>
     * Example: `539b7f74-3832-474e-a955-6d69c5df12d0`
     *
     * @example "539b7f74-3832-474e-a955-6d69c5df12d0"
     */
