    }) {
        this.customerId = customerId;
        this.invoiceLineItems = invoiceLineItems;
        this.businessID = businessID;
        this.invoiceId = invoiceId;
        this.invoiceStatus = invoiceStatus;
        this.invoiceS3bucket = invoiceS3bucket;
