export enum ValidBillingCycles {
    monthly = 'monthly',
    'annualToDate' = 'annualToDate',
    topUp = 'topUp',
}

/**
 * The default percentage (of the `topUpAmount`) of the customer wallet balance at which a top up is triggered.
 */
export const DEFAULT_TOP_UP_THRESHOLD = '0.2';

/**
 * The time frame when an automatic bill should be sent leave empty for no automated billing
 * <br>  • `monthly` - The customer is billed at the beginning of every month for the prior month.
 * <br>  • `annualToDate` - The customer is billed once a year.
 * <br>  • `topUp` - The customer pre pays for their usage. Usage is deducted from the customer wallet every hour, and the wallet is automatically topped up to the `topUpAmount` whenever the balance drops below the `topUpThreshold`. Only valid on `usage-based` offerings.
 * <br><br>
 *
 * Example `"monthly"`
 * @example "monthly"
 */
@IsEnum(ValidBillingCycles)
@IsOptional()
@ApiProperty({ enum: ValidBillingCycles, default: ValidBillingCycles.monthly })
public billingCycle?: ValidBillingCycles;

/**
 * The amount the customer wallet is topped up to whenever the wallet balance drops below the `topUpThreshold`.
 * Required when the `billingCycle` is `topUp`, and only allowed when the `billingCycle` is `topUp`.
 * Only positive numerical strings are allowed.
 * <br><br>Example: `"100.00"` for $100.00.
 * @example "100.00"
 */
@IsNumberString()
@IsOptional()
@Validate(IsNumericStringGreaterToZeroValidator)
public topUpAmount?: string;

/**
 * The percentage of the `topUpAmount` which the customer wallet balance must drop below before the wallet is topped up again.
 * Only allowed when the `billingCycle` is `topUp`. Defaults to `"0.2"`, which means that the wallet is topped up
 * whenever the balance is below 20% of the `topUpAmount`.
 * <br><br>Example: `"0.2"` for 20% of the `topUpAmount`.
 * @example "0.2"
 */
@IsNumberString()
@IsOptional()
@Validate(IsNumericStringGreaterThanOrEqualToZeroValidator)
public topUpThreshold?: string;

