/**
 * Validates the top up (prepaid credit) related fields of an offering.
 * <br> • A `topUpAmount` is required when the billing cycle is `topUp`
 * <br> • The top up fields are only valid on offerings with a `topUp` billing cycle
 * <br> • Subscription offerings cannot use the `topUp` billing cycle
 */
public static validateTopUpFields({
    billingCycle,
    offeringType,
    topUpAmount,
    topUpThreshold,
}: {
    billingCycle?: ValidBillingCycles;
    offeringType?: string;
    topUpAmount?: string;
    topUpThreshold?: string;
}): void {
    const isTopUpBillingCycle = billingCycle === ValidBillingCycles.topUp;
    if (isTopUpBillingCycle && offeringType === OfferingType.subscription) {
        throw new BadRequestException('The topUp billing cycle is not allowed for subscription offerings');
    }
    if (isTopUpBillingCycle && !topUpAmount) {
        throw new BadRequestException('A topUpAmount is required for offerings with a topUp billing cycle');
    }
    if (!isTopUpBillingCycle && (topUpAmount || topUpThreshold)) {
        throw new BadRequestException(
            'topUpAmount and topUpThreshold are only allowed on offerings with a topUp billing cycle',
        );
    }
}

