        return SupportedMeasurementFrequencies.everyHour as unknown as string;
    }
}

/**
 * Determines if the offering is a prepaid credit (top up) offering
 */
public isTopUp(): boolean {
    return this.billingCycle === ValidBillingCycles.topUp;
}

/**
 * The wallet balance at, or below which, the customer wallet is topped up again.
 * Calculated as `topUpThreshold * topUpAmount`
 */
public getTopUpThresholdBalance(): number {
    return (
        parseFloat(this.topUpThreshold ? this.topUpThreshold : DEFAULT_TOP_UP_THRESHOLD) *
        parseFloat(this.topUpAmount ? this.topUpAmount : '0')
    );
}

/**
 * Reads the current customer wallet (credit) balance
 */
protected async getWalletBalance(creditService?: CreditService): Promise<number> {
    const walletService = creditService ? creditService : this.creditService;
    const { balance } = await walletService.findCreditBalance({
        businessID: this.businessID,
        customerId: this.customerId,
    });
    return parseFloat(balance ? balance : '0');
}

/**
 * Tops the customer wallet back up to the `topUpAmount` if, and only if, the current wallet balance is
 * below the top up threshold (`topUpThreshold * topUpAmount`).
 * The exact difference between the current balance and the `topUpAmount` is charged to the customer
 * with an invoice, the payment of that invoice is stored as credit on the customer wallet.
 *
 * @returns the invoiceId of the top up invoice, if a top up occurred
 */
public async topUpWallet({
    customer,
    creditService,
    balance,
}: {
    customer?: ReadCustomerResponseData;
    creditService?: CreditService;
    balance?: number;
} = {}): Promise<string | void> {
    const walletService = creditService ? creditService : this.creditService;
    if (!this.isTopUp() || !this.topUpAmount) {
        return;
    }
    if (!walletService) {
        Offering.logger.error(
            `Unable to top up the wallet of customer: ${this.customerId} no credit service was provided`,
        );
        AuditService.publishEvent({
            message: 'Failed to top up customer wallet, no credit service was provided',
            topic: AuditScope.ERROR,
            data: [{ customerId: this.customerId, businessID: this.businessID, offeringId: this.offeringId }],
        });
        return;
    }
    const currentBalance = typeof balance === 'number' ? balance : await this.getWalletBalance(walletService);
    const topUpAmount = parseFloat(this.topUpAmount);
    const thresholdBalance = this.getTopUpThresholdBalance();
    Offering.logger.log(
        `Evaluating top up for customer: ${this.customerId}. Balance: ${currentBalance}, threshold: ${thresholdBalance}, topUpAmount: ${topUpAmount}`,
    );
    if (currentBalance >= thresholdBalance) {
        // The customer still has enough funds in their wallet, no top up is required.
        return;
    }
    const amountToCharge = parseFloat((topUpAmount - currentBalance).toFixed(2));
    if (amountToCharge <= 0) {
        return;
    }
    const timestamp = new Date().toISOString();
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(
        new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, amountToCharge, 'Prepaid credit top up'),
    );
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId: this.customerId,
        items: lineItems,
        invoiceDate: timestamp,
        currency: Offering.getCurrency({ customer, offering: this }),
    });
    // The payment of the top up invoice is stored as credit on the customer wallet
    await walletService.create({
        transactionAmount: amountToCharge.toFixed(2),
        businessID: this.businessID,
        customerId: this.customerId,
        timestamp,
        metadata: {
            invoiceId,
            offeringId: this.offeringId,
            reason: `Top up for ${this.offeringName}`,
        },
    });
    return invoiceId;
}

/**
 * Deducts the usage of the current top up interval (one hour) from the customer wallet, and then evaluates
 * if the wallet needs to be topped up again with the updated balance.
 * No usage invoice is created for top up offerings, the usage is only deducted from the customer wallet.
 *
 * @returns the invoiceId of the top up invoice, if a top up occurred
 */
public async processTopUpBilling({
    customer,
    startDateOverride,
    endDateOverride,
    creditService,
    deductUsage = true,
}: {
    customer?: ReadCustomerResponseData;
    startDateOverride?: Date;
    endDateOverride?: Date;
    creditService?: CreditService;
    deductUsage?: boolean;
}): Promise<string | void> {
    const walletService = creditService ? creditService : this.creditService;
    if (!walletService) {
        Offering.logger.error(
            `Unable to process top up billing for customer: ${this.customerId} no credit service was provided`,
        );
        AuditService.publishEvent({
            message: 'Failed to process top up billing, no credit service was provided',
            topic: AuditScope.ERROR,
            data: [{ customerId: this.customerId, businessID: this.businessID, offeringId: this.offeringId }],
        });
        return;
    }
    let balance = await this.getWalletBalance(walletService);
    if (deductUsage) {
        const { startTime, endTime } = Billing.billingCycleToTimeRange(ValidBillingCycles.topUp);
        const startDate = startDateOverride ? startDateOverride : new Date(startTime);
        const endDate = endDateOverride ? endDateOverride : new Date(endTime);
        const lineItems = new InvoiceLineItems();
        await Offering.getLineItemsForUsage({
            startDate,
            endDate,
            customer,
            lineItems,
            negative: false,
            businessID: this.businessID,
            customerId: this.customerId,
            customerService: this.customerService,
            offeringInstance: this,
            dimensions: this.dimensions,
        });
        let usageTotal = lineItems.getTotal();
        if (this?.discount?.name) {
            if (!this.discount.endDate || !DatetimeUtils.isDateInPast(new Date(this.discount.endDate))) {
                Offering.addDiscountLineItem(this.discount, lineItems);
                usageTotal = lineItems.getTotal();
            }
        }
        usageTotal = parseFloat(usageTotal.toFixed(2));
        Offering.logger.log(
            `Top up usage for customer: ${this.customerId} between ${startDate.toISOString()} and ${endDate.toISOString()} is ${usageTotal}`,
        );
        if (usageTotal > 0) {
            // The usage is always deducted from the wallet, even if the usage is greater than the current balance
            await walletService.create(
                {
                    transactionAmount: (usageTotal * -1).toFixed(2),
                    businessID: this.businessID,
                    customerId: this.customerId,
                    timestamp: new Date().toISOString(),
                    metadata: {
                        offeringId: this.offeringId,
                        reason: `Usage for ${this.offeringName}`,
                    },
                },
                false,
                true,
            );
            balance = parseFloat((balance - usageTotal).toFixed(2));
        }
    }
    // The top up is always evaluated with the balance after the usage has been deducted
    return this.topUpWallet({ customer, creditService: walletService, balance });
}

