            discountName,
            discountPercentage,
            offeringEnrollmentDate,
            freeTrialEndDate,
            businessID,
            dimensionOverrides,
        } = dbModel;
        let discount: CustomerContractDiscount | undefined;
        if (discountName || discountPercentage) {
            discount = new CustomerContractDiscount({
                name: discountName,
                percentage: discountPercentage,
                endDate: discountEndDate,
